"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["27017"],{85711(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.criterio_desempate.regra_tipo_invalido","status":422,"titulo":"A regra referenciada n\xe3o \xe9 do tipo criterio_desempate"},"descricao":{"codigo":"uniplus.selecao.criterio_desempate.regra_tipo_invalido","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Este c\xf3digo cobre duas situa\xe7\xf5es distintas, ambas sobre a coer\xeancia de tipo\\nda regra referenciada:","- O `regraCodigo`/`regraVersao` de um crit\xe9rio de desempate existe no\\n  `rol_de_regras`, mas o tipo cadastrado da regra n\xe3o \xe9\\n  `CRITERIO_DESEMPATE`. O cat\xe1logo \xe9 compartilhado por v\xe1rios tipos de\\n  regra do m\xf3dulo Sele\xe7\xe3o \u2014 o c\xf3digo sozinho n\xe3o garante o tipo certo.\\n- A regra existe e \xe9 do tipo `CRITERIO_DESEMPATE`, mas o c\xf3digo dela n\xe3o\\n  corresponde a nenhuma das quatro variantes reconhecidas\\n  (`DESEMPATE_MAIOR_NOTA_ETAPA`, `DESEMPATE_MAIOR_IDADE`,\\n  `DESEMPATE_IDOSO`, `DESEMPATE_CONDICAO_SOBRE_DADO`) \u2014 o vocabul\xe1rio do tipo\\n  `CRITERIO_DESEMPATE` \xe9 fechado, e um c\xf3digo fora dele n\xe3o tem\\n  argumentos correspondentes para montar.","Roda logo depois de\\n[`regra_nao_encontrada`](/erros/uniplus.selecao.criterio_desempate.regra_nao_encontrada)\\nresolver a exist\xeancia da regra. O processamento \xe9 sequencial por crit\xe9rio:\\no primeiro que falhar interrompe a passada, sem acumular com nenhuma outra\\nviola\xe7\xe3o.","Esta causa n\xe3o aparece na leitura de vers\xf5es j\xe1 publicadas, inclusive na retifica\xe7\xe3o em ato \xfanico: a regra guardada n\xe3o \xe9 consultada novamente no cat\xe1logo. Um c\xf3digo desconhecido na configura\xe7\xe3o publicada recebe `envelope_codec.regra_desconhecida`."],"comoResolver":["Confirme, no cat\xe1logo de regras, que o c\xf3digo e a vers\xe3o declarados s\xe3o de\\nfato uma regra do tipo `CRITERIO_DESEMPATE`, com um c\xf3digo de uma das\\nquatro variantes reconhecidas. Se a inten\xe7\xe3o era outra regra (distribui\xe7\xe3o\\nde vagas, ajuste, cascata), reveja qual refer\xeancia pertence a qual campo do\\ncorpo do pedido."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Criterio desempate"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);